.card {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);display:flex;flex-direction:column;overflow:clip;color:var(--color-foreground);font-size:var(--text-sm)}
:where([data-doop-theme="light"]) .card {--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.card[data-variant="default"], .card[data-variant="interactive"] {background:var(--color-card);border-radius:.5rem;border:var(--spacing-hairline) solid var(--color-card-hairline);box-shadow:var(--sh-card)}
.card[data-variant="interactive"] {cursor:pointer;user-select:none;transition:background-color 100ms}
.card[data-variant="interactive"]:hover, .card[data-variant="interactive"][data-state="hover"] {background:var(--color-card-hover)}
.card[data-state="focus"] {outline:1px solid var(--focus-ring,var(--color-ring));outline-offset:-1px}
.card[data-variant="panel"] {background:var(--color-panel);border-radius:var(--radius-xl);border:var(--spacing-hairline) solid var(--color-card-hairline);box-shadow:var(--sh-card)}
.card[data-variant="ghost"] {background:transparent;border-radius:.5rem}
.card .hd {display:flex;align-items:center;gap:8px;border-bottom:var(--spacing-hairline) solid var(--color-border-1);padding:12px 16px}
.card .tt {font-size:var(--text-base);font-weight:var(--font-weight-medium);letter-spacing:var(--tracking-tight)}
.card .ct {padding:16px;color:var(--color-muted-foreground-1)}
.card[data-rows="true"] .ct {padding:0}
.card[data-rows="true"] .ct > * + * {border-top:var(--spacing-hairline) solid var(--color-border-1)}
.card .ft {display:flex;align-items:center;justify-content:flex-end;gap:8px;border-top:var(--spacing-hairline) solid var(--color-border-1);padding:12px 16px}
